"""Smoke check usable from both Python and the frozen Windows application."""
import tempfile
from pathlib import Path
import runpy
import numpy as np
import engine
from project import export_script,export_bundle

def main():
    pipeline={'version':1,'steps':[engine.new_step('brightness_contrast')]}
    pipeline['steps'][0]['params']['brightness']=-20
    with tempfile.TemporaryDirectory() as folder:
        root=Path(folder);script=root/'export.py';export_script(script,pipeline);export_bundle(root/'generation.zip',pipeline)
        # Only load a script generated by this process from its own trusted engine.
        namespace=runpy.run_path(str(script),run_name='generated_smoke_test')
        image=np.full((8,8,3),100,np.uint8);actual=namespace['run'](image,pipeline)[0]
        np.testing.assert_array_equal(actual,80)
    print('Packaged runtime and both export modes passed.')
if __name__=='__main__':main()
